fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Check if the vector is empty
    if v.is_empty() {
        return false;
    }
    
    // Check if all characters are lowercase letters
    for &c in v {
        if c < 'a' || c > 'z' {
            return false;
        }
    }
    true
}

fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}